/**
 * Credential of the `ssh` provider : an ed25519 key pair generated by the
 * instance, plus the connection parameters and the **pinned host key**.
 *
 * Spec : docs/spec/vaubaan-gateway.md §0 "Connection", §6 (credentials
 *        encrypted at rest), §7.2.
 * ADR  : docs/decisions/plugin-contract-and-credential-spec.md D2 (`ssh-key`).
 *
 * The host runs the flow : it generates the key pair, shows the public key
 * for the operator to append to `~/.ssh/authorized_keys` on the target, and
 * collects the four fields below. The private key never leaves the instance
 * and is stored encrypted. The host key fingerprint is part of the
 * credential and is verified on every connection
 * (`transport.ts`) : a host that presents another key is refused, never
 * trusted on first use.
 */

import { createHash } from 'node:crypto';

import {
  expectCredentialKind,
  type CredentialSecret,
  type SshKeyCredentialSpec,
} from '@vaubaan/plugin-sdk';

/** Hostname or IPv4 literal. IPv6 literals are not accepted : the ref must fit a slice identifier. */
export const SSH_HOST_PATTERN = '^[A-Za-z0-9](?:[A-Za-z0-9.-]*[A-Za-z0-9])?$';
export const SSH_PORT_PATTERN =
  '^(?:[1-9][0-9]{0,3}|[1-5][0-9]{4}|6[0-4][0-9]{3}|65[0-4][0-9]{2}|655[0-2][0-9]|6553[0-5])$';
export const SSH_USER_PATTERN = '^[a-z_][a-z0-9_-]{0,31}\\$?$';
/** OpenSSH `SHA256:` fingerprint, base64 with or without the trailing `=`. */
export const SSH_FINGERPRINT_PATTERN = '^SHA256:[A-Za-z0-9+/]{43}=?$';

export const SSH_DEFAULT_PORT = 22;

export const sshCredential: SshKeyCredentialSpec = {
  kind: 'ssh-key',
  algorithm: 'ed25519',
  fields: [
    {
      name: 'host',
      label: 'Host',
      secret: false,
      placeholder: 'vps-1.example.com',
      pattern: SSH_HOST_PATTERN,
      help: 'Hostname or IPv4 address. It becomes the resource ref the agent cites.',
    },
    {
      name: 'port',
      label: 'Port',
      secret: false,
      required: false,
      placeholder: String(SSH_DEFAULT_PORT),
      pattern: SSH_PORT_PATTERN,
      help: `SSH port, ${SSH_DEFAULT_PORT} when empty.`,
    },
    {
      name: 'user',
      label: 'Login user',
      secret: false,
      placeholder: 'deploy',
      pattern: SSH_USER_PATTERN,
      help: 'The account whose authorized_keys receives the public key shown after generation. Its sudoers entry bounds what the agent can escalate to.',
    },
    {
      name: 'host_key_fingerprint',
      label: 'Host key fingerprint',
      secret: false,
      placeholder: 'SHA256:…',
      pattern: SSH_FINGERPRINT_PATTERN,
      help: 'Run `ssh-keyscan -t ed25519 <host> | ssh-keygen -lf -` on a machine that already trusts the host and paste the SHA256 value. The connection refuses any other host key.',
    },
  ],
};

/** The facts every connection needs, narrowed from the decrypted secret. */
export interface SshTarget {
  readonly host: string;
  readonly port: number;
  readonly user: string;
  readonly privateKeyPem: string;
  /** Normalised `SHA256:<base64>` — the pin every connection is verified against. */
  readonly hostKeyFingerprint: string;
}

/**
 * Narrow the secret the host hands the plugin. Throws `CredentialKindMismatch`
 * on the wrong kind and a plain `Error` when a field is missing or malformed —
 * both mean a host bug, not a provider error, so neither is an `UpstreamAuthError`.
 */
export function sshTarget(secret: CredentialSecret): SshTarget {
  const key = expectCredentialKind('ssh', secret, 'ssh-key');
  const host = key.fields.host;
  const user = key.fields.user;
  const rawPort = key.fields.port;
  const fingerprint = key.fields.host_key_fingerprint;

  if (typeof host !== 'string' || !new RegExp(SSH_HOST_PATTERN).test(host)) {
    throw new Error("ssh credential: field 'host' is missing or is not a hostname / IPv4 address");
  }
  if (typeof user !== 'string' || !new RegExp(SSH_USER_PATTERN).test(user)) {
    throw new Error("ssh credential: field 'user' is missing or is not a POSIX user name");
  }
  let port = SSH_DEFAULT_PORT;
  if (rawPort !== undefined && rawPort !== '') {
    if (typeof rawPort !== 'string' || !new RegExp(SSH_PORT_PATTERN).test(rawPort)) {
      throw new Error("ssh credential: field 'port' is not a TCP port");
    }
    port = Number(rawPort);
  }
  const normalised = normalizeFingerprint(fingerprint);
  if (normalised === null) {
    throw new Error(
      "ssh credential: field 'host_key_fingerprint' is missing or is not a 'SHA256:…' fingerprint",
    );
  }
  if (typeof key.privateKeyPem !== 'string' || key.privateKeyPem.length === 0) {
    throw new Error('ssh credential: the private key is missing');
  }
  return { host, port, user, privateKeyPem: key.privateKeyPem, hostKeyFingerprint: normalised };
}

/** `SHA256:<base64>` without the trailing `=`, as OpenSSH prints it ; `null` when malformed. */
export function normalizeFingerprint(value: unknown): string | null {
  if (typeof value !== 'string') return null;
  const trimmed = value.trim();
  if (!new RegExp(SSH_FINGERPRINT_PATTERN).test(trimmed)) return null;
  return trimmed.replace(/=+$/, '');
}

/** OpenSSH-style fingerprint of a raw public host key blob. */
export function fingerprintOf(hostKey: Uint8Array): string {
  const digest = createHash('sha256').update(hostKey).digest('base64');
  return `SHA256:${digest.replace(/=+$/, '')}`;
}

/** True iff the presented host key matches the pinned fingerprint. */
export function hostKeyMatches(pinned: string, hostKey: Uint8Array): boolean {
  const expected = normalizeFingerprint(pinned);
  return expected !== null && fingerprintOf(hostKey) === expected;
}
